// IT: cancel (sense 2, subscription) -> disdici (Maria 2026-10-13)
const MODE = 'all';
const EDITS = [
 {term:'cancel',iso:'it',tr:'disdici'}
];
const B = 'https://api.lokalise.com/api2/projects/';
const GL = '46552447679363c70f7ef8.58193285';
return [
  { json: { label: 'langs', url: B + GL + '/languages?limit=500', edits: EDITS, mode: MODE } },
  { json: { label: 'glossary', url: B + GL + '/glossary-terms?limit=500' } }
];

const C = $('Config').first().json; const E = C.edits;
const norm = s => String(s == null ? '' : s).trim().toLowerCase();
const isoToId = {}; const idToIso = {}; const terms = []; const errors = [];
for (const it of $input.all()) { const b = it.json.body || {};
  if (Array.isArray(b.languages)) { for (const l of b.languages) { if (!isoToId[l.lang_iso]) isoToId[l.lang_iso] = l.lang_id; idToIso[l.lang_id] = l.lang_iso; } continue; }
  if (Array.isArray(b.data)) { for (const t of b.data) terms.push(t); continue; }
  errors.push({ status: it.json.statusCode, body: JSON.stringify(b).slice(0, 200) }); }
const byTerm = {}; const plan = []; const problems = [];
for (const e of E) {
  const m = terms.filter(t => norm(t.term) === norm(e.term)); const langId = isoToId[e.iso];
  if (m.length !== 1 || !langId) { problems.push({ e, matches: m.length, langId }); continue; }
  const t = m[0];
  if (!byTerm[t.id]) byTerm[t.id] = { id: t.id, term: t.term, tr: (t.translations || []).map(x => ({ langId: x.langId, translation: x.translation, description: x.description || '' })) };
  const cur = byTerm[t.id].tr.find(x => x.langId === langId);
  plan.push({ id: t.id, term: t.term, iso: e.iso, langId, old: cur ? cur.translation : null, new: e.tr });
  if (cur) cur.translation = e.tr; else byTerm[t.id].tr.push({ langId, translation: e.tr, description: '' });
}
let ids = Object.keys(byTerm);
if (C.mode === 'test') ids = ids.slice(0, 1);
const body = { terms: ids.map(id => ({ id: Number(id), translations: byTerm[id].tr })) };
const blocked = errors.length > 0 || terms.length < 500 || problems.length > 0;
return [{ json: { termsN: terms.length, errors, problems, plan, blocked, mode: C.mode, termIds: ids, body } }];

const p = $('Prepare').first().json; const r = $input.first().json; const b = r.body || {};
const data = b.data || b.terms || []; const mism = []; let checked = 0;
for (const s of p.body.terms) { const t = data.find(d => d.id === s.id) || {};
  for (const x of s.translations) { checked++; const y = (t.translations || []).find(z => z.langId === x.langId);
    if (!y || String(y.translation) !== String(x.translation)) mism.push({ id: s.id, langId: x.langId, sent: x.translation, got: y ? y.translation : null }); } }
return [{ json: { status: r.statusCode, written: data.map(d => d.term), checked, mism, raw: data.length ? '' : JSON.stringify(b).slice(0, 600) } }];
